const rows = $input.all();
const dailyData = {};

for (const item of rows) {
  const r = item.json;
  if (!r.date) continue;

  let dateStr = String(r.date).split('T')[0];
  if(dateStr.includes('-')) {
     const parts = dateStr.split('-');
     if(parts.length === 3) dateStr = `${parts[2]}.${parts[1]}`;
  }

  const status = String(r.status || '').toUpperCase();
  const errs = parseInt(r.errors_count) || 0;

  if (!dailyData[dateStr]) {
    dailyData[dateStr] = { errors: 0, isOk: true };
  }

  dailyData[dateStr].errors += errs;
  if (status !== 'OK' || errs > 0) {
    dailyData[dateStr].isOk = false;
  }
}

const allDates = Object.keys(dailyData);
const last7Dates = allDates.slice(-7);

let totalErrors = 0;
let okDays = 0;
let failedDays = 0;
const chartDates = [];
const chartErrors = [];

for (const d of last7Dates) {
  const data = dailyData[d];
  chartDates.push(d);
  chartErrors.push(data.errors);
  totalErrors += data.errors;

  if (data.isOk) {
    okDays++;
  } else {
    failedDays++;
  }
}

const totalDays = last7Dates.length || 1;
const uptimePercent = Math.round((okDays / totalDays) * 100);

const chartConfig = {
  type: 'bar',
  data: {
    labels: chartDates,
    datasets: [{
      data: chartErrors,
      backgroundColor: chartErrors.map(e => e > 0 ? '#e63946' : '#2a9d8f'),
      borderRadius: 4,
      minBarLength: 10
    }]
  },
  options: {
    legend: { display: false },
    title: { display: true, text: 'Аптайм по дням', fontColor: '#ffffff', fontSize: 16 },
    scales: {
      yAxes: [{ ticks: { beginAtZero: true, fontColor: '#a0aabc', stepSize: 1, suggestedMax: Math.max(...chartErrors, 3) }, gridLines: { color: '#2b303b' } }],
      xAxes: [{ ticks: { fontColor: '#a0aabc' }, gridLines: { display: false } }]
    }
  }
};

const chartUrl = `https://quickchart.io/chart?c=${encodeURIComponent(JSON.stringify(chartConfig))}&bkg=${encodeURIComponent('#1b1f27')}&w=800&h=400`;

return [{
  json: {
    weekly_days_checked: totalDays,
    weekly_ok_days: okDays,
    weekly_failed_days: failedDays,
    weekly_uptime: `${uptimePercent}%`,
    weekly_total_errors: totalErrors,
    chart_url: chartUrl
  }
}];

const items = $input.all();
const targetPages = [];

for (const item of items) {
  const row = item.json;
  const isActive = String(row.active).toUpperCase() === 'TRUE' || row.active === true || row.active === 1;
  const expectedStatus = String(row.expected_status || row['ожидаемый статус'] || row.status || '200').trim();

  if (isActive && row.url && expectedStatus.includes('200')) {
    targetPages.push({
      json: {
        url: String(row.url).trim(),
        expected_products: parseInt(row.expected_products || row.min_products) || 0,
        expected_names: String(row.expected_names || row.names || '').trim()
      }
    });
  }
}

return targetPages;

let uptimeData = { weekly_uptime: "—", weekly_ok_days: 0, weekly_failed_days: 0, weekly_total_errors: 0, chart_url: "" };
try { uptimeData = $('Calculate Uptime').first()?.json || uptimeData; } catch(e) {}

let pagesFilter = [];
try { pagesFilter = $('Filter Targets for Content').all() || []; } catch(e) {}

const htmls = $input.all();
const weekDate = new Date().toISOString().split('T')[0];

let pagesInSearch = "—", sqi = "—", wmErrorsCount = 0, wmStatusText = "В НОРМЕ";
try {
  const summaryNode = $('Yandex API - Get Host Summary').first();
  if (summaryNode && summaryNode.json) {
    const data = summaryNode.json;
    pagesInSearch = data.searchable_pages_count !== undefined ? data.searchable_pages_count : "—";
    sqi = data.sqi || "—";
    if (data.site_problems) {
      const fatal = data.site_problems.FATAL || 0;
      const critical = data.site_problems.CRITICAL || 0;
      wmErrorsCount = fatal + critical;
      if (wmErrorsCount > 0) wmStatusText = `⚠️ Ошибок: ${wmErrorsCount} (Фатальных: ${fatal}, Критических: ${critical})`;
    }
  }
} catch (e) {}

function extractSeoBlock(html) {
  if (!html) return '';
  const articleMatch = html.match(/<article[\s\S]*?<\/article>/i);
  if (articleMatch) return articleMatch[0];
  const staticMatch = html.match(/<div[^>]*class=["'][^"']*static-text[^"']*["'][^>]*>([\s\S]*?)<\/div>/i);
  if (staticMatch) return staticMatch[0];
  const widgetMatch = html.match(/class=["'][^"']*widget-type_system_widget_v4_collection_description[\s\S]*?<\/div>\s*<\/div>/i);
  if (widgetMatch) return widgetMatch[0];
  return '';
}

let errorLogs = [];
let successLogs = [];
let totalWarnings = 0;
let shortErrorsForTg = [];

for (let i = 0; i < htmls.length; i++) {
  const pageData = pagesFilter[i] ? pagesFilter[i].json : {};
  const origUrl = pageData.url || `Страница #${i+1}`;
  const shortUrl = origUrl.replace('https://boosterpro.ru', '');
  const expectedProducts = parseInt(pageData.expected_products) || 0;
  const expectedNamesStr = pageData.expected_names || "";

  const rawHtml = htmls[i] && htmls[i].json ? (htmls[i].json.html_snippet || "") : "";

  if (!rawHtml) {
    let errorReason = "Нет данных от узла (таймаут сети или пустой ответ)";
    if (htmls[i] && htmls[i].json) {
      errorReason = htmls[i].json.message || htmls[i].json.error || htmls[i].json.statusCode || JSON.stringify(htmls[i].json).substring(0, 150);
    }
    errorLogs.push(`### ❌ ${shortUrl}\n- **Лог ответа сервера:** ${errorReason}`);
    shortErrorsForTg.push(`❌ ${shortUrl} (Ошибка ответа)`);
    totalWarnings++;
    continue;
  }

  let pageIssues = [];
  let productCount = 0;
  let cleanHtml = rawHtml;

  // 1. ИЗОЛЯЦИЯ КАТАЛОГА
  const cutoffRegex = /(widget-type_widget_v4_article_previews|widget-type_widget_v4_special_products_tabs|<footer[^>]*>|class=["'][^"']*site-footer["'])/i;
  const cutoffMatch = rawHtml.match(cutoffRegex);
  if (cutoffMatch && cutoffMatch.index > 5000) { 
    cleanHtml = rawHtml.substring(0, cutoffMatch.index);
  }

  // 2. СЧИТАЕМ ТОВАРЫ ПО УНИКАЛЬНОМУ КЛАССУ
  const productTitles = cleanHtml.match(/class=["'][^"']*product-preview__title[^"']*["']/gi);
  productCount = productTitles ? productTitles.length : 0;

  // 3. ПРОВЕРКА ОБЩЕГО КОЛИЧЕСТВА
  if (expectedProducts > 0 && productCount !== expectedProducts) {
    const diff = Math.abs(expectedProducts - productCount);
    pageIssues.push(`⚠️ **Ассортимент:** Найдено **${productCount}** шт. (Должно быть ровно: ${expectedProducts}, разница: ${diff} шт.)`);
  } else if (productCount === 0 && shortUrl.includes('/collection/')) {
    pageIssues.push(`⚠️ **Ассортимент:** Категория пустая (0 товаров)!`);
  }

  // 4. ПРОВЕРКА НАЛИЧИЯ КОНКРЕТНЫХ ТОВАРОВ
  if (expectedNamesStr) {
    const expectedArray = expectedNamesStr.split(',').map(s => s.trim()).filter(s => s);
    let missingItems = [];
    for (const itemName of expectedArray) {
      if (!cleanHtml.toLowerCase().includes(itemName.toLowerCase())) {
        missingItems.push(itemName);
      }
    }
    if (missingItems.length > 0) {
      pageIssues.push(`❌ **Отсутствуют важные товары:** ${missingItems.join(', ')}`);
    }
  }

  // 5. ПРОВЕРКА МИКРОРАЗМЕТКИ (С ВЫТАСКИВАНИЕМ РАСПРОДАННЫХ ТОВАРОВ)
  const jsonLdMatches = rawHtml.match(/<script[^>]+type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi);
  let outOfStockItems = [];

  if (!jsonLdMatches || jsonLdMatches.length === 0) {
    pageIssues.push(`❌ **Микроразметка:** Блок JSON-LD не найден`);
  } else {
    let validSchemas = [];
    let hasJsonError = false;

    for (const scriptTag of jsonLdMatches) {
      const contentMatch = scriptTag.match(/<script[^>]*>([\s\S]*?)<\/script>/i);
      if (contentMatch && contentMatch[1]) {
        try {
          const parsed = JSON.parse(contentMatch[1].trim());

          if (parsed['@type'] === 'ItemList' && parsed.itemListElement) {
             for (const item of parsed.itemListElement) {
                 if (item.item && item.item.offers && item.item.offers.availability) {
                     if (item.item.offers.availability.includes('OutOfStock')) {
                         outOfStockItems.push(item.item.name || "Неизвестный товар");
                     }
                 }
             }
          }

          const checkType = (obj) => {
              if (Array.isArray(obj)) return obj.map(o => o['@type']).join(',');
              if (obj['@graph'] && Array.isArray(obj['@graph'])) return obj['@graph'].map(o => o['@type']).join(',');
              return obj['@type'] || 'Неизвестно';
          };
          validSchemas.push(checkType(parsed));
        } catch (e) {
          hasJsonError = true;
        }
      }
    }
    if (hasJsonError) {
      pageIssues.push(`❌ **Микроразметка:** Ошибка синтаксиса JSON (битый код)`);
    } else {
      const schemaString = validSchemas.join(', ');

      let requiredSchemas = ['BreadcrumbList'];
      if (shortUrl.includes('/collection/')) {
        requiredSchemas.push('ItemList', 'FAQPage');
      } else if (shortUrl.includes('/blogs/')) {
        requiredSchemas.push('ItemList', 'FAQPage', 'Article');
      } else if (shortUrl.includes('/product/')) {
        requiredSchemas.push('Product', 'FAQPage');
      }

      let missingSchemas = [];
      for (const reqSchema of requiredSchemas) {
        if (!schemaString.includes(reqSchema)) {
          missingSchemas.push(reqSchema);
        }
      }

      if (missingSchemas.length > 0) {
        pageIssues.push(`⚠️ **Микроразметка:** Отсутствуют блоки: ${missingSchemas.join(', ')}`);
      }
    }
  }

  if (outOfStockItems.length > 0) {
     const uniqueOutOfStock = [...new Set(outOfStockItems)];
     pageIssues.push(`⚠️ **Наличие:** Распроданы: ${uniqueOutOfStock.join(', ')}`);
  }

  // 6. Проверка картинок
  const seoHtml = extractSeoBlock(rawHtml);
  if (seoHtml) {
    const imgMatches = seoHtml.match(/<img[^>]+>/g) || [];
    let missingAltCount = 0;
    for (const img of imgMatches) {
      if (img.includes('mc.yandex.ru') || img.includes('served_assets') || img.includes('favicon') || img.includes('data:image')) continue;
      const altMatch = img.match(/alt=["']([^"']*)["']/i);
      if (!altMatch || !altMatch[1].trim()) missingAltCount++;
    }
    if (missingAltCount > 0) {
      pageIssues.push(`⚠️ **Картинки:** Без тега ALT в тексте (${missingAltCount} шт.)`);
    }
  }

  if (pageIssues.length > 0) {
    totalWarnings++;
    errorLogs.push(`### ⚠️ ${shortUrl} (Товаров: ${productCount})\n` + pageIssues.map(item => `- ${item}`).join('\n'));
    shortErrorsForTg.push(`⚠️ ${shortUrl}`);
  } else {
    successLogs.push(`- ✅ **${shortUrl}** (Товаров: ${productCount} шт. | Разметка: В норме)`);
  }
}

let mdDetails = `# Еженедельный SEO-Отчет (boosterpro.ru)\n**Дата отчета:** ${weekDate}\n\n`;
mdDetails += `## 1. Сводка Яндекс.Вебмастера\n- **Страниц в поиске Яндекса:** ${pagesInSearch}\n- **ИКС сайта:** ${sqi}\n- **Статус проблем:** ${wmStatusText}\n\n`;
mdDetails += `## 2. Стабильность за 7 дней\n- **Uptime:** ${uptimeData.weekly_uptime}\n- **Сбоев за неделю:** ${uptimeData.weekly_total_errors}\n\n`;
mdDetails += `## 3. Выявленные отклонения\n\n`;

if (errorLogs.length === 0) {
  mdDetails += `✅ **Проблем не обнаружено. Все проверенные категории в норме.**\n\n`;
} else {
  mdDetails += errorLogs.join('\n\n') + '\n\n';
}

mdDetails += `## 4. Успешно проверенные страницы (${successLogs.length} шт.)\n\n`;
mdDetails += successLogs.join('\n');

const overallStatus = (totalWarnings > 0 || wmErrorsCount > 0) ? "WARNING" : "OK";

let tgSummary = `📈 <b>ЕЖЕНЕДЕЛЬНЫЙ SEO-ОТЧЕТ (${weekDate})</b>\n\n`;
tgSummary += `• <b>Uptime:</b> ${uptimeData.weekly_uptime}\n`;
tgSummary += `• <b>Индекс Яндекса:</b> ${pagesInSearch} стр. | ИКС: ${sqi}\n`;

if (totalWarnings > 0 || wmErrorsCount > 0) {
  tgSummary += `\n⚠️ <b>Найдены замечания (${totalWarnings} кат.):</b>\n`;
  tgSummary += shortErrorsForTg.slice(0, 10).join('\n');
  if (shortErrorsForTg.length > 10) tgSummary += `\n... и еще ${shortErrorsForTg.length - 10}`;
  tgSummary += `\n\nФайл с полным логом прикреплен ниже.`;
} else {
  tgSummary += `\n✅ <b>Сайт работает идеально. Проверено ${successLogs.length} категорий.</b>`;
}

// Формируем чистый текст для колонки weekly_summary в Google Sheets
let tableSummary = "";
if (totalWarnings > 0 || wmErrorsCount > 0) {
  let issues = [];
  if (wmErrorsCount > 0) issues.push(`Я.Вебмастер: ${wmErrorsCount} ошибок`);
  if (shortErrorsForTg.length > 0) {
    issues.push("Проблемы в: " + shortErrorsForTg.map(s => s.replace('⚠️ ', '').replace('❌ ', '')).join(', '));
  }
  tableSummary = issues.join(' | ');
} else {
  tableSummary = "✅ Замечаний нет";
}

return [{
  json: { 
    week_date: weekDate, 
    status: overallStatus, 
    telegram_summary: tgSummary,
    table_summary: tableSummary,
    daily_uptime: uptimeData.weekly_uptime,
    webmaster_pages_in_search: pagesInSearch,
    webmaster_errors: wmErrorsCount,
    content_warnings: totalWarnings,
    chart_url: uptimeData.chart_url,
    markdown_text: mdDetails
  }
}];

const sourceData = $('Process & Aggregate Weekly').first().json;

const mdText = sourceData.markdown_text || "Ошибка: не удалось прочитать текст отчета из предыдущей ноды.";
const weekDate = sourceData.week_date || new Date().toISOString().split('T')[0];

return [{
  json: {
    week_date: weekDate,
    status: sourceData.status || "OK",
    table_summary: sourceData.table_summary || "",
    daily_uptime: sourceData.daily_uptime || "",
    webmaster_pages_in_search: sourceData.webmaster_pages_in_search || "",
    webmaster_errors: sourceData.webmaster_errors || 0,
    content_warnings: sourceData.content_warnings || 0
  },
  binary: {
    markdown_file: {
      data: Buffer.from(mdText, 'utf-8').toString('base64'),
      mimeType: 'text/markdown',
      fileName: `Weekly_SEO_Report_${weekDate}.md`
    }
  }
}];

const originals = $('Prepare Active Items').all();
const responses = $input.all();

// Определение инициатора запуска
let initiator = "Ежедневный анализ";
try {
  const tgData = $("Telegram Trigger1").first();
  if (tgData && tgData.json) {
    const user = tgData.json.message?.from?.username || tgData.json.message?.from?.first_name;
    initiator = user ? `По вызову в ТГ (@${user})` : "По вызову в ТГ";
  }
} catch (e) {
  initiator = "Ежедневный анализ";
}

let errorCount = 0;
let logErrorDetails = [];
const dateStr = new Date().toISOString().split('T')[0];

let mdDetails = `# Ежедневный SEO-Отчет (boosterpro.ru)\n**Инициатор:** ${initiator}\n**Дата:** ${dateStr}\n\n## Детализация по страницам\n\n`;

function cleanText(str) {
  if (!str) return '';
  return str.replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
}

function extractTag(html, regex) {
  const match = html.match(regex);
  return match ? cleanText(match[1]) : '';
}

function extractMeta(html, name) {
  const regex1 = new RegExp(`<meta[^>]*name=["']${name}["'][^>]*content=["']([^"']*)["']`, 'i');
  const regex2 = new RegExp(`<meta[^>]*content=["']([^"']*)["'][^>]*name=["']${name}["']`, 'i');
  const match = html.match(regex1) || html.match(regex2);
  return match ? cleanText(match[1]) : '';
}

for (let i = 0; i < originals.length; i++) {
  const orig = originals[i].json;
  const res = responses[i] ? responses[i].json : null;

  let status = "ERR";
  let rawHtml = "";
  let location = "";
  let errDetail = "";

  if (res && res.http_status) {
    status = res.http_status;
    rawHtml = res.html_snippet || "";
    location = res.location || "";
    errDetail = res.error || "";
  }

  let icon = "✅";
  let notes = [];
  let shortUrl = orig.url.replace('https://boosterpro.ru', '');

  if (status === "ERR") {
    icon = "❌";
    const errText = errDetail ? `[Сбой: ${errDetail.slice(0, 30)}]` : "[Сбой сети/таймаут]";
    notes.push(errText);
    errorCount++;
  } else {
    // 1. Проверка HTTP Status
    if (status !== orig.expected_status) {
      icon = "❌";
      notes.push(`[Статус: ${status}, ждали: ${orig.expected_status}]`);
      errorCount++;
    }

    // 2. Проверки для Target страниц
    if (orig.type === 'target') {
      const robots = extractMeta(rawHtml, 'robots').toLowerCase();
      const googlebot = extractMeta(rawHtml, 'googlebot').toLowerCase();

      if (robots.includes('noindex') || googlebot.includes('noindex')) {
        icon = "❌";
        notes.push("[noindex!]");
        errorCount++;
      }

      // H1 Check
      if (orig.expected_h1) {
        const actualH1 = extractTag(rawHtml, /<h1[^>]*>([\s\S]*?)<\/h1>/i);
        if (!actualH1) {
          icon = "❌"; notes.push("[H1 отсутствует]"); errorCount++;
        } else if (!actualH1.toLowerCase().includes(orig.expected_h1.toLowerCase())) {
          icon = "⚠️"; notes.push(`[H1 расходится]`); errorCount++;
        }
      }

      // Title Check
      if (orig.expected_title) {
        const actualTitle = extractTag(rawHtml, /<title[^>]*>([\s\S]*?)<\/title>/i);
        if (!actualTitle) {
          icon = "❌"; notes.push("[Title отсутствует]"); errorCount++;
        } else if (!actualTitle.toLowerCase().includes(orig.expected_title.toLowerCase())) {
          icon = "⚠️"; notes.push(`[Title расходится]`); errorCount++;
        }
      }

      // Description Check
      if (orig.expected_desc) {
        const actualDesc = extractMeta(rawHtml, 'description');
        if (!actualDesc) {
          icon = "❌"; notes.push("[Desc отсутствует]"); errorCount++;
        } else if (!actualDesc.toLowerCase().includes(orig.expected_desc.toLowerCase())) {
          icon = "⚠️"; notes.push(`[Desc расходится]`); errorCount++;
        }
      }
    }

    // 3. Проверки для Redirect страниц
    if (orig.type === 'redirect') {
      const locClean = location.replace('https://boosterpro.ru', '');
      const expClean = orig.expected_target.replace('https://boosterpro.ru', '');

      if (orig.expected_target && locClean !== expClean) {
        icon = "❌";
        notes.push(`[Кривой редирект на: ${locClean || 'неизвестно'}]`);
        errorCount++;
      }
    }
  }

  if (notes.length > 0) {
    logErrorDetails.push(`${icon} ${shortUrl} ${notes.join(' ')}`);
  }

  const noteStr = notes.length > 0 ? ` ${notes.join(' ')}` : '';
  mdDetails += `- ${icon} **${status}** | ${shortUrl}${noteStr}\n`;
}

mdDetails += `\n**Всего ошибок/предупреждений:** ${errorCount}`;

let tgSummary = `📊 <b>SEO-Мониторинг (${initiator}):</b>\n\n`;
tgSummary += `Проверено страниц: ${originals.length}\n`;

if (errorCount > 0) {
  tgSummary += `⚠️ <b>Найдены замечания: ${errorCount}</b>\n`;
  tgSummary += `Подробный лог прикреплен в файле ниже.`;
} else {
  tgSummary += `✅ <b>Все страницы в норме. Ошибок нет.</b>\n`;
  tgSummary += `Детальный лог в прикрепленном файле.`;
}

return [{
  json: {
    telegram_text: tgSummary,
    markdown_text: mdDetails,
    log_date: dateStr,
    log_status: errorCount === 0 ? "OK" : "ERROR",
    log_total: originals.length,
    log_errors: errorCount,
    log_details: logErrorDetails.length > 0 ? logErrorDetails.join('\n') : "—",
    log_initiator: initiator
  }
}];

const sourceData = $('Process & Aggregate Daily').first().json;
const mdText = sourceData.markdown_text || "Ошибка создания отчета.";
const dateStr = sourceData.log_date || new Date().toISOString().split('T')[0];

return [{
  json: sourceData,
  binary: {
    data: {
      data: Buffer.from(mdText, 'utf-8').toString('base64'),
      mimeType: 'text/markdown',
      fileName: `Daily_SEO_Report_${dateStr}.md`
    }
  }
}];

const items = $input.all();
const activeItems = [];

for (const item of items) {
  const row = item.json;
  // Пропускаем неактивные строки
  const isActive = String(row.active).toUpperCase() === 'TRUE' || row.active === true || row.active === 1;
  if (isActive && row.url) {
    activeItems.push({
      json: {
        url: String(row.url).trim(),
        type: String(row.type || 'target').trim().toLowerCase(),
        expected_status: parseInt(row.expected_status) || 200,
        expected_target: String(row.expected_target || '').trim(),
        expected_h1: String(row.expected_h1 || '').trim(),
        expected_title: String(row.expected_title || '').trim(),
        expected_desc: String(row.expected_desc || '').trim()
      }
    });
  }
}

return activeItems;
